-- System permissions
REVOKE CREATE USER FROM ROLE maintainer;
REVOKE DROP USER FROM ROLE maintainer;
REVOKE ALTER USER FROM ROLE maintainer;
REVOKE CREATE SCHEMA FROM ROLE maintainer;
REVOKE DROP SCHEMA FROM ROLE maintainer;
REVOKE ALTER DEFAULT PRIVILEGES FROM ROLE maintainer;
REVOKE ACCESS CATALOG FROM ROLE maintainer;
REVOKE ACCESS SYSTEM TABLE FROM ROLE maintainer;
REVOKE CREATE TABLE FROM ROLE maintainer;
REVOKE DROP TABLE FROM ROLE maintainer;
REVOKE ALTER TABLE FROM ROLE maintainer;
REVOKE CREATE OR REPLACE FUNCTION FROM ROLE maintainer;
REVOKE CREATE OR REPLACE EXTERNAL FUNCTION FROM ROLE maintainer;
REVOKE DROP FUNCTION FROM ROLE maintainer;
REVOKE CREATE OR REPLACE PROCEDURE FROM ROLE maintainer;
REVOKE DROP PROCEDURE FROM ROLE maintainer;
REVOKE CREATE OR REPLACE VIEW FROM ROLE maintainer;
REVOKE DROP VIEW FROM ROLE maintainer;
REVOKE CREATE MODEL FROM ROLE maintainer;
REVOKE DROP MODEL FROM ROLE maintainer;
REVOKE CREATE DATASHARE FROM ROLE maintainer;
REVOKE ALTER DATASHARE FROM ROLE maintainer;
REVOKE DROP DATASHARE FROM ROLE maintainer;
REVOKE CREATE LIBRARY FROM ROLE maintainer;
REVOKE DROP LIBRARY FROM ROLE maintainer;
REVOKE CREATE ROLE FROM ROLE maintainer;
REVOKE DROP ROLE FROM ROLE maintainer;
REVOKE TRUNCATE TABLE FROM ROLE maintainer;
REVOKE VACUUM FROM ROLE maintainer;
REVOKE ANALYZE FROM ROLE maintainer;
REVOKE CANCEL FROM ROLE maintainer;
REVOKE IGNORE RLS FROM ROLE maintainer;
REVOKE EXPLAIN RLS FROM ROLE maintainer;
REVOKE EXPLAIN MASKING FROM ROLE maintainer;
REVOKE ALL FROM ROLE maintainer;
REVOKE ALL PRIVILEGES FROM ROLE maintainer;

-- Multiple system permissions and multiple role targets
REVOKE CREATE USER, DROP USER, ALTER USER FROM ROLE role1, role2;
REVOKE CREATE SCHEMA, DROP SCHEMA FROM ROLE role1, ROLE role2;
REVOKE CREATE TABLE, DROP TABLE FROM ROLE role1, FROM ROLE role2;

-- Object and role revocations
REVOKE SELECT ON TABLE qa_tickit.sales FROM GROUP qa_users, GROUP ro_users;
REVOKE ADMIN OPTION FOR ROLE sample_role1 FROM user1;
